  "requirement_definitions": [
    {
      "id": "DMSR-5029",
      "title": "Generate Data Quality Report Within Speciﬁed Time",
      "text": "The DMS shall generate a nightly Data Quality Report within time dqReportComplTime in both human-readable and machine-readable forms."
    },
    {
      "id": "DMSR-1305",
      "title": "Generate DMS Performance Report Within Speciﬁed Time",
      "text": "The DMS shall generate a nightly DMS Performance Report within time perfReportComplTime in both human-readable and machine-readable forms."
    },
    {
      "id": "DMSR-7078",
      "title": "Generate Calibration Report Within Speciﬁed Time",
      "text": "The DMS shall generate a nightly Calibration Report within time calibReportComplTime in both human-readable and machine-readable forms."
    },
    {
      "id": "DMSR-2704",
      "title": "Calibration Production Processing",
      "text": "The DMS shall be capable of producing calibration data products on an as-needed basis, consistent with monitoring the health and performance of the instrument, the availability of raw calibration exposures, the temporal stability of the calibrations, and of the SRD requirements for calibration accuracy."
    },
    {
      "id": "DMSR-7444",
      "title": "Associating Objects across data releases",
      "text": "It shall be possible to associate an Object in one data release to the most likely match in the Object table from another data release. This shall be possible without the previous data releases being online."
    },
    {
      "id": "DMSR-1141",
      "title": "Access Controls of Level 3 Data Products",
      "text": "All Level 3 data products shall be conﬁgured to have the ability to have access restricted to the owner, a list of people, a named group, or be completely public."
    },
    {
      "id": "DMSR-5272",
      "title": "Level 3 Data Import",
      "text": "The DMS shall be able to ingest tables from common ﬁle formats (e.g. FITS tables, CSV ﬁles with supporting metadata) to facilitate the loading of external catalogs and the production of Level-3 data products."
    },
    {
      "id": "DMSR-4074",
      "title": "DAC resource allocation for Level 3 processing",
      "text": "The DMS shall provide a resource allocation mechanism for the DACs that allows the prioritization and allocation of resources to a variety of Level 3 processing activities."
    },
    {
      "id": "DMSR-4575",
      "title": "Level 3 Data Product Self Consistency",
      "text": "The DMS shall provide a means for ensuring that users’ Level 3 processing tasks can be carried out on self-consistent inputs - i.e., catalogs, images, metadata, calibrations, camera conﬁguration data, etc., that match each other and all arise from consistent Level 1 and Level 2 processings."
    }
  ],
